// Shared contract for every truthgate module. Owned by the lead: coders do not edit this file.
// Need a change? Write it in tasks.md under "Contract requests" and the lead applies it.
// Imports use .ts extensions (Node type stripping); tsc rewrites them to .js in dist/.

// ---------------------------------------------------------------------------------------------
// Specs
// ---------------------------------------------------------------------------------------------

export type Lang = 'python' | 'ts' | 'js' | 'java' | 'csharp' | 'go' | 'rust';

/** Parsed input generator. Source syntax: int[a,b] decimal[a,b,places] str[max] bool list<T>[max]
 *  record{a:T,b:T} oneof[v1,v2,...] (JSON literals). */
export type TypeSpec =
  | { t: 'int'; min: number; max: number }
  | { t: 'decimal'; min: number; max: number; places: number }
  | { t: 'str'; max: number }
  | { t: 'bool' }
  | { t: 'list'; of: TypeSpec; max: number }
  | { t: 'record'; fields: Record<string, TypeSpec> }
  | { t: 'oneof'; values: unknown[] };

export interface Property {
  name: string;
  expr: string;
}

/** One operation of a `kind: sequence` spec. `inputs` are generator strings like Spec.inputs. */
export interface Op {
  name: string;
  inputs: Record<string, string>;
}

export interface ProveConfig {
  tool: 'rocq' | 'dafny';
  file: string; // relative to repo root
  theorem: string; // rocq theorem / dafny lemma or method name
}

export interface Spec {
  id: string;
  /** `path/to/file.ext::functionName`, path relative to repo root, forward slashes. */
  target: string;
  lang: Lang;
  kind: 'function' | 'sequence';
  /** function specs: argument name -> generator string. */
  inputs: Record<string, string>;
  /** Preconditions; generated inputs failing any are discarded. */
  requires: string[];
  /** function specs: postconditions over the inputs and `out`. */
  ensures: Property[];
  /** sequence specs only. */
  ops?: Op[];
  /** sequence specs only: expressions over `state` (from the shim's `state` op), checked after every op. */
  invariant?: Property[];
  /** default: Config.defaultRuns */
  runs?: number;
  /** true: a `crash` result is not by itself a failure. */
  allowCrash?: boolean;
  prove?: ProveConfig;
  /** How to start this spec's shim (non-js/ts). Default: the adapter's convention for the shim path
   *  from `shimTemplate`. Tokens: {root} {shim}. Example: ["go","run","{shim}"]. */
  shim?: { command: string[]; cwd?: string };
  /** Path of the spec file, relative to repo root, forward slashes. Set by the loader. */
  file: string;
}

// ---------------------------------------------------------------------------------------------
// Expression language (src/core/expr.ts exports `expr: ExprApi`)
// Grammar: literals (num, str, bool, null, [a,b], {k:v}), identifiers, a.b, a[i], + - * / % ,
// == != < <= > >=, and or not, `a implies b`, all(x in xs: e), any(x in xs: e),
// calls to the fixed helper set only: len sum min max abs round sorted perm unique count range keys values.
// No eval, no other calls, no property access on prototypes.
// ---------------------------------------------------------------------------------------------

export type Expr =
  | { k: 'lit'; v: unknown }
  | { k: 'var'; name: string }
  | { k: 'list'; items: Expr[] }
  | { k: 'obj'; entries: [string, Expr][] }
  | { k: 'get'; obj: Expr; key: string }
  | { k: 'index'; obj: Expr; index: Expr }
  | { k: 'un'; op: 'not' | '-'; arg: Expr }
  | { k: 'bin'; op: '+' | '-' | '*' | '/' | '%' | '==' | '!=' | '<' | '<=' | '>' | '>=' | 'and' | 'or' | 'implies'; l: Expr; r: Expr }
  | { k: 'quant'; q: 'all' | 'any'; v: string; over: Expr; body: Expr }
  | { k: 'call'; fn: Helper; args: Expr[] };

export type Helper =
  | 'len' | 'sum' | 'min' | 'max' | 'abs' | 'round' | 'sorted' | 'perm'
  | 'unique' | 'count' | 'range' | 'keys' | 'values';

export interface ExprApi {
  /** Throws ExprError with a position on bad syntax or unknown helper. */
  parse(src: string): Expr;
  /** Pure. Throws ExprError on type errors. Numbers compare (== != < <= > >=) with tolerance
   *  1e-9 * max(1, |a|, |b|) so decimal inputs don't drift; toPython must match.
   *  Quantifiers are capped at 1e6 total iterations per evaluate() (ExprError past it).
   *  Runner mapping: ExprError in `requires` -> UNVERIFIED; ExprError in an ensures/invariant whose
   *  requires held -> FALSIFIED with that input (wrong-typed output is a failure, not a dodge). */
  evaluate(e: Expr, env: Record<string, unknown>): unknown;
  /** Python source equivalent of `e`, using helpers from the generated harness module. */
  toPython(e: Expr): string;
}

// ---------------------------------------------------------------------------------------------
// Verdicts and reports
// ---------------------------------------------------------------------------------------------

export type VerdictKind =
  | 'PROVEN'
  | 'PROVEN_MODEL_ONLY'
  | 'FALSIFIED'
  | 'TESTED'
  | 'WEAK_SPEC'
  | 'UNVERIFIED';

export interface Verdict {
  specId: string;
  /** Property name; absent for spec-level verdicts (e.g. UNVERIFIED: toolchain missing). */
  property?: string;
  kind: VerdictKind;
  /** One human-readable line. TESTED must state N and the 3/N bound. UNVERIFIED must state why. */
  detail: string;
  runs?: number;
  /** Shrunk failing input (function) or op sequence (sequence). */
  counterexample?: unknown;
  seed?: number;
  durationMs: number;
}

export interface TamperFinding {
  file: string;
  line?: number;
  rule:
    | 'assert-removed'
    | 'skip-added'
    | 'test-deleted'
    | 'spec-changed'
    | 'spec-deleted'
    | 'approvals-edited'
    | 'config-edited';
  detail: string;
}

export interface DeepReport {
  mutation?: {
    caught: number;
    total: number;
    survivors: { file: string; line: number; desc: string }[];
    durationMs: number;
  };
  proofs: Verdict[];
}

export interface RunReport {
  verdicts: Verdict[];
  tamper: TamperFinding[];
  /** Non-blocking notes, e.g. "src/x.py changed but has no spec". */
  warnings: string[];
  changedFiles: string[];
  /** true iff any FALSIFIED verdict or any tamper finding. */
  blocking: boolean;
  durationMs: number;
  deep?: DeepReport;
}

// ---------------------------------------------------------------------------------------------
// Config and state (src/core/config.ts, src/core/state.ts)
// ---------------------------------------------------------------------------------------------

/** `.truthgate/config.json`; every field optional on disk, defaults filled by loadConfig. */
export interface Config {
  budgetSeconds: number; // 60
  deepBudgetSeconds: number; // 120
  loopCap: number; // 3
  seed: number; // 42
  defaultRuns: number; // 100
  provers: { rocq?: string; dafny?: string }; // dirs or exe paths; e.g. rocq: "D:/Rocq-Platform~9.1~2026.01/bin"
  python: { native: boolean }; // true when Hypothesis is available/accepted
  /** Globs (forward slashes) treated as source for "changed but no spec" warnings. */
  sourceGlobs: string[];
}

/** `.truthgate/state.json` (gitignored). */
export interface State {
  consecutiveBlocks: number;
  lastRunAt?: string;
}

/** `.truthgate/approved.json` (committed): spec id -> sha256 of the spec file's normalized text (LF). */
export interface Approvals {
  version: 1;
  specs: Record<string, { sha256: string; approvedAt: string }>;
  /** sha256 of the canonical JSON of `specs`; detects hand edits. */
  integrity: string;
}

// ---------------------------------------------------------------------------------------------
// Runners and languages (src/runner/index.ts, src/lang/index.ts)
// ---------------------------------------------------------------------------------------------

export type CallResult =
  | { ok: true; out: unknown }
  | { ok: false; kind: 'rejected' | 'crash'; error: string };

/** A live connection to the code under test (shim process, or in-process import for js/ts). */
export interface FunctionCaller {
  call(fn: string, input: Record<string, unknown>): Promise<CallResult>;
  reset(): Promise<void>;
  state(): Promise<unknown>;
  close(): Promise<void>;
}

export interface LanguageAdapter {
  lang: Lang;
  /** true, or a reason string why the toolchain/shim is unavailable (-> UNVERIFIED). */
  available(root: string): Promise<true | string>;
  /** Start the shim (or import the module) for this spec's target. */
  open(spec: Spec, root: string): Promise<FunctionCaller>;
  /** Ready-to-save shim source for this spec, plus where to save it. `root` lets Go/Rust read go.mod/Cargo.toml.
   *  path '' = no shim needed (js/ts). */
  shimTemplate(spec: Spec, root?: string): { path: string; source: string };
  /** Test-file globs (forward slashes) for tamper detection. */
  testFileGlobs: string[];
  /** Line patterns that mark a skipped/disabled test. */
  skipMarkers: RegExp[];
  /** Line patterns that count as an assertion. */
  assertPatterns: RegExp[];
  /** Line comment prefix, used by mutation to skip comment lines. */
  lineComment: string;
}

export interface RunOptions {
  seed: number;
  runs: number;
  /** Absolute epoch ms; stop and return UNVERIFIED (timeout) for unfinished properties. */
  deadline: number;
  config: Config;
}

// ---------------------------------------------------------------------------------------------
// Agents (src/agents/index.ts)
// ---------------------------------------------------------------------------------------------

export type AgentId =
  | 'claude' | 'codex' | 'gemini' | 'copilot' | 'cursor'
  | 'amp' | 'windsurf' | 'opencode' | 'cline' | 'kiro';

export interface FileChange {
  path: string; // relative to repo root
  /** create: new file (skip if identical, refuse if different unless merge). merge: structured JSON/TOML merge.
   *  append-block: insert/replace a `<!-- truthgate:begin -->...<!-- truthgate:end -->` block. */
  action: 'create' | 'merge' | 'append-block';
  content: string;
  note?: string;
}

export interface AgentInstaller {
  id: AgentId;
  /** true for agents with a blocking/continuing stop hook. */
  enforces: boolean;
  /** Pure planning: compute changes without writing. The CLI prints them for --dry-run or applies them. */
  plan(root: string): Promise<FileChange[]>;
  /** Manual steps to print (e.g. user-scope MCP config we refuse to edit). */
  manualSteps?: string[];
  /** Translate a report into this agent's stop-hook output. `capped` = loop cap reached (allow the stop). */
  hookOutput?(report: RunReport, capped: boolean): { stdout: string; exitCode: number };
}

